<script setup>
import {computed,ref,watch,onUnmounted} from 'vue';
import {CheckCircle2,Info,Download,Search,Pause,Play} from 'lucide-vue-next';
import MediaThumb from './MediaThumb.vue';
import PageControls from './PageControls.vue';
import {size,percent,jobLabel,activeStatus,matchesSearch,remaining,plannedLabel} from './helpers';
const props=defineProps({jobs:Array,resources:Array,busy:Boolean,counts:Object,paging:Object,loading:Boolean,queuePaused:Boolean});const emit=defineEmits(['pause','resume','retry','cancel','preview','saving','query','queue']);
const filter=ref('all'),search=ref(''),filters=[{id:'all',label:'全部'},{id:'active',label:'进行中'},{id:'completed',label:'已完成'},{id:'failed',label:'未成功'}];
function inFilter(j,id){return id==='all'||(id==='active'?activeStatus(j.status)||j.status==='paused':id==='failed'?['failed','cancelled'].includes(j.status):j.status==='completed')}
const shown=computed(()=>props.jobs.filter(j=>inFilter(j,filter.value)&&matchesSearch(j,search.value)));
const resourceMap=computed(()=>new Map(props.resources.map(r=>[r.id,r])));
let searchTimer;
watch([search,filter],()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>emit('query',{query:search.value,filter:filter.value,page:1}),250)});
onUnmounted(()=>clearTimeout(searchTimer));
</script>
<template><section class="download-panel"><div class="phone-page-title"><h1>电脑下载队列</h1><p>文件保存在 Mac，完成后可取回 iPhone</p></div><div class="phone-queue"><div><strong>{{queuePaused?'队列已暂停':'电脑自动处理任务'}}</strong><p>{{queuePaused?'正在下载的任务会继续，后续任务等待':'手机离开此页面，电脑也会继续下载'}}</p></div><button :disabled="busy" @click="emit('queue',!queuePaused)"><component :is="queuePaused?Play:Pause" :size="17"/>{{queuePaused?'继续队列':'暂停队列'}}</button></div><label v-if="jobs.length||search||(counts?.all>0)" class="search-field"><Search :size="19"/><span class="sr-only">搜索下载任务</span><input v-model="search" type="search" placeholder="搜索下载任务" aria-label="搜索下载任务"/></label><div class="filter-tabs" role="group" aria-label="筛选下载任务"><button v-for="f in filters" :key="f.id" :class="{selected:filter===f.id}" :aria-pressed="filter===f.id" @click="filter=f.id">{{f.label}}<span class="filter-count">{{counts?.[f.id]??jobs.filter(j=>inFilter(j,f.id)).length}}</span></button></div>
  <ul class="media-list" v-if="shown.length"><li v-for="j in shown" :key="j.id" class="job-row"><MediaThumb :resource="resourceMap.get(j.resourceId)||j.resource" tall/><div class="job-detail"><h3 :title="j.name">{{j.name}}</h3><p class="job-status" :class="{success:j.status==='completed'}"><CheckCircle2 v-if="j.status==='completed'" :size="17"/>{{plannedLabel(j,queuePaused)}}<template v-if="j.status==='downloading'"> · {{size(j.done)}} / {{size(j.total)}}</template></p><p v-if="j.priority" class="job-plan">{{j.priority>0?'优先下载':'空闲时下载'}}</p><p v-if="j.status==='completed'">{{size(j.total)}}<template v-if="j.quality"> · {{j.quality}}</template></p><div v-if="activeStatus(j.status)||j.status==='paused'" class="progress-line"><progress :value="percent(j)" max="100" aria-label="下载进度"/><span>{{Math.floor(percent(j))}}%</span></div><p v-if="j.status==='downloading'&&j.speed>0" class="transfer-speed">{{size(j.speed)}}/s<template v-if="j.eta>0"> · 剩余{{remaining(j.eta)}}</template></p><p v-if="j.error" class="job-error">{{j.error}}</p><div class="job-actions"><template v-if="j.status==='completed'"><button :disabled="busy" @click="emit('preview',j)">预览</button><a class="button primary" :href="'/files/'+encodeURIComponent(j.id)" download @click="emit('saving')">保存到手机</a></template><template v-else><button v-if="activeStatus(j.status)&&!['merging','validating'].includes(j.status)" :disabled="busy" @click="emit('pause',j.id)">暂停</button><button v-if="(j.status==='paused'||j.resumeAvailable)&&!activeStatus(j.status)" :disabled="busy" @click="emit('resume',j.id)">继续</button><button v-else-if="['failed','cancelled'].includes(j.status)" :disabled="busy" @click="emit('retry',j)">重试</button><button v-if="activeStatus(j.status)||j.status==='paused'" class="text-button" :disabled="busy" @click="emit('cancel',j.id)">取消</button></template></div></div></li></ul>
  <div v-else class="empty-state"><Download :size="30"/><strong>{{search?'没有匹配的下载任务':filter==='completed'?'还没有已完成的文件':filter==='failed'?'没有未成功的任务':'还没有下载任务'}}</strong><p>{{search?'试试其他关键词。':'在资源页点击下载，电脑会处理任务。'}}</p></div>
  <PageControls :paging="paging" :loading="loading" @page="page=>emit('query',{page})"/><p class="download-hint"><Info :size="18"/>文件先下载到电脑，再保存到 iPhone。</p>
</section></template>
